/**
 * Formats an integer amount of cents as a decimal currency string: an optional
 * leading '-' for negative amounts, the absolute whole currency units, and
 * exactly two fraction digits. No currency symbol is included.
 *
 * formatAmount(123) === '1.23', formatAmount(0) === '0.00', formatAmount(-1) === '-0.01'
 */
export function formatAmount(cents: number): string {
  const sign = cents < 0 ? '-' : '';
  const absolute = Math.abs(cents);
  return sign + Math.floor(absolute / 100) + '.' + String(absolute % 100).padStart(2, '0');
}
EOF
